mapper.select:
select d1.id,d1.dname,d1.dtype,d1.dtel,d1.dfax,d1.description, d1.supdepartment, COALESCE(d2.dname,'顶级部门') as supdepartment1, date_format(d1.establishmentdate,'%Y-%m-%d') as establishmentdate1, d1.parent_id,d1.order_num,d1.leader_id from sys_department d1 left join sys_department d2 on COALESCE(d1.parent_id, d1.supdepartment) = d2.id where 1=1
and d1.dname like concat('%',#{dname},'%')
and d1.dtype = #{dtype}
limit #{startIndex}, #{pageSize}

mapper.update:
update sys_department
dname = #{dname}, dtype = #{dtype}, dtel = #{dtel}, dfax = #{dfax}, description = #{description}, supdepartment = #{supdepartment}, parent_id = #{parent_id}, order_num = #{order_num}, leader_id = #{leader_id}
where id = #{id}
